def sha(path):
    return hashlib.sha256(open(path, "rb").read()).hexdigest()


def build_story(sid, d):
    sdir = os.path.join(BASE, sid)
    os.makedirs(sdir, exist_ok=True)
    # episode
    ep = {"episode_id": sid, "persona": d["persona"], "initial_kb": d["initial_kb"],
          "turns": [{"case_id": t["case_id"], "turn_type": "reply",
                     "input": {"messages": t["messages"], "clock": t["clock"],
                               "may_decline": t["may_decline"], **({"intent": t["intent"]} if t.get("intent") else {})},
                     "gold": {}} for t in d["turns"]]}
    with open(os.path.join(sdir, "episode.json"), "w", encoding="utf-8") as f:
        json.dump(ep, f, ensure_ascii=False, indent=1)
    # reference
    ref = {"story_id": sid, "turns": {}}
    sanitized = []
    for t in d["turns"]:
        r = dict(d["refs"][t["case_id"]])
        r.setdefault("case_id", t["case_id"])
        for atom in r.get("required_memory_atoms") or []:
            # 语义纪律：required_this_turn 的原子必须来自更早轮次/种子——
            # 当前轮信息本就在 prompt 里，不构成记忆考核；来源为当前轮时自动降级。
            src = atom.get("source") or {}
            if atom.get("required_this_turn") and src.get("kind") == "message" \
                    and src.get("case_id") == t["case_id"]:
                atom["required_this_turn"] = False
                sanitized.append("%s/%s" % (t["case_id"], atom.get("atom_id")))
        ref["turns"][t["case_id"]] = r
    if sanitized:
        print("  sanitized required_this_turn (sourced from current turn):",
              ",".join(sanitized))
    with open(os.path.join(sdir, "reference.json"), "w", encoding="utf-8") as f:
        json.dump(ref, f, ensure_ascii=False, indent=1)
    # timeline（turn_clocks/message_index 由 episode 派生，杜绝手抄错位）
    tl = {"kind": "story_timeline_v2", "story_id": sid, "timezone": "Asia/Shanghai",
          "turn_clocks": [{"case_id": t["case_id"], "clock": t["clock"]} for t in d["turns"]],
          "message_index": [], "events": d["timeline"]["events"],
          "relationship": d["timeline"]["relationship"],
          "revisions": d["timeline"]["revisions"],
          "future_policy": d["timeline"]["future_policy"]}
    for t in d["turns"]:
        for i, m in enumerate(t["messages"]):
            tl["message_index"].append({"case_id": t["case_id"], "message_id": "m%d" % i,
                                        "speaker": m["role"], "ts": m["ts"], "quote": m["text"]})
    with open(os.path.join(sdir, "timeline.json"), "w", encoding="utf-8") as f:
        json.dump(tl, f, ensure_ascii=False, indent=1)
    # audit.md
    a = d["audit"]
    audit = """# {sid} {title} — Stage2 作者审计

## 0. 性质与暴露
作者=AI（ZCode main worker-AI），synthetic 虚构人物与对话；不含真实用户素材；exposure 如实登记 dev_candidate_stage2，frozen_at=null，experiments_used 空。

## 1. 生活动机
{motive}

## 2. 连续性与回扣
{continuity}

## 3. ME 历史与边界
{me_boundary}

## 4. no_reply / 媒体局限
{media}

## 5. 参考卡质量
{quality}

## 6. 已知风险
{risk}

## 7. 出口检查
{exit_check}
""".format(sid=sid, title=d["title"], motive=a["生活动机"], continuity=a["连续性与回扣"],
           me_boundary=a["ME历史与边界"], media=a["no_reply媒体局限"],
           quality=a["参考卡质量"], risk=a["已知风险"], exit_check=a["出口检查"])
    with open(os.path.join(sdir, "audit.md"), "w", encoding="utf-8") as f:
        f.write(audit)
    # runner copy + exposure（hashes 在其余文件写完后计算）
    rc_rel = os.path.join("benchmark", "episodes", sid + ".json")
    with open(os.path.join(ROOT, rc_rel), "w", encoding="utf-8") as f:
        json.dump(ep, f, ensure_ascii=False, indent=1)
    exposure = {"kind": "story_exposure_v2", "story_id": sid, "title": d["title"],
                "themes": d["themes"], "author": "ZCode main worker-AI (synthetic)",
                "author_type": "AI", "real_user_material": False,
                "source_notes": "虚构人物与对话；不含真实用户素材；不声称真人经历。",
                "readers": ["author"], "independent_review": False,
                "review_note": "同 worker 自检；不是独立封存集。",
                "created_at": "2026-10-28", "frozen_at": None,
                "status": "dev_candidate_stage2", "experiments_used": [],
                "dev_exposed": True, "validation_claim": False, "turns": len(d["turns"]),
                "may_decline_turns": [t["case_id"] for t in d["turns"] if t["may_decline"]],
                "hashes": {n: sha(os.path.join(sdir, n)) for n in
                           ("episode.json", "reference.json", "timeline.json", "audit.md")},
                "runner_copy": rc_rel.replace("\\", "/"),
                "notes": "Stage2 首批（W06）；12位自然故事；冻结与未调参验证在后续批次。"}
    with open(os.path.join(sdir, "exposure.json"), "w", encoding="utf-8") as f:
        json.dump(exposure, f, ensure_ascii=False, indent=1)
    return sid


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--stories", default=",".join(STORY_DEFS))
    a = ap.parse_args()
    os.makedirs(BASE, exist_ok=True)
    man_path = os.path.join(BASE, "STAGE2_MANIFEST.json")
    man = {"kind": "story_v2_manifest", "stage": "stage2", "count": 0, "stories": []}
    if os.path.isfile(man_path):
        man = json.load(open(man_path, encoding="utf-8"))
    entries = {s["story_id"]: s for s in man.get("stories", [])}
    for sid in a.stories.split(","):
        sid = sid.strip()
        if not sid or sid not in STORY_DEFS:
            print("SKIP unknown story:", sid)
            continue
        build_story(sid, STORY_DEFS[sid])
        sdir = os.path.join(BASE, sid)
        entries[sid] = {"story_id": sid,
                        "files": {n: sha(os.path.join(sdir, n)) for n in
                                  ("episode.json", "reference.json", "timeline.json", "audit.md")}}
        print("BUILT", sid)
    man["stories"] = [entries[k] for k in sorted(entries)]
    man["count"] = len(man["stories"])
    with open(man_path, "w", encoding="utf-8") as f:
        json.dump(man, f, ensure_ascii=False, indent=1)
    print("MANIFEST count=%d -> %s" % (man["count"], man_path))


if __name__ == "__main__":
    main()
